import styled from '@emotion/styled';
import { StyledChipRoot } from 'components/ChartHeader/ChartHeader.styles';

import { PORTFOLIO_PIE_CHART_HEIGHT } from './config/portfolioPieChartConfig';

type StyledPortfolioPieChartPlotProps = {
  skeleton?: boolean;
};

export const StyledPortfolioPieChartRoot = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
  border: '1px solid #14141414',
  borderRadius: '16px',
  overflow: 'visible',
});

export const StyledPortfolioPieChartTitle = styled.div({
  padding: '24px 16px',
  borderBottom: '1px solid #14141429',
  boxSizing: 'border-box',
});

export const StyledPortfolioPieChartTitleRow = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: '16px',
  width: '100%',
  minWidth: 0,
});

export const StyledPortfolioPieChartHeading = styled.h3({
  margin: 0,
  padding: 0,
  fontSize: '20px',
  fontWeight: 600,
  lineHeight: '120%',
  color: '#141414',
  fontFamily: 'Barlow, sans-serif',
  textAlign: 'left',
});

export const StyledPortfolioPieChartPeriodChipWrap = styled.div({
  flexShrink: 0,
});

export const StyledPortfolioPieChartPeriodChip = styled(StyledChipRoot)({});

export const StyledPortfolioPieChartTitleSkeleton = styled.div({
  width: '100%',
  minHeight: '20px',
});

export const StyledPortfolioPieChartInner = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  width: '100%',
  gap: '12px',
  padding: '16px 24px 24px',
  boxSizing: 'border-box',
});

export const StyledPortfolioPieLegend = styled.div({
  display: 'flex',
  flexWrap: 'wrap',
  justifyContent: 'center',
  alignContent: 'center',
  alignItems: 'center',
  gap: '10px 14px',
  width: '100%',
  maxWidth: '100%',
  marginBottom: '4px',
  boxSizing: 'border-box',
  textAlign: 'center',
});

export const StyledPortfolioPieLegendItem = styled.div({
  display: 'inline-flex',
  alignItems: 'center',
  gap: '4px',
  fontSize: '12px',
  lineHeight: '140%',
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 500,
  color: '#141414',
  textDecoration: 'none',
  opacity: 1,
});

export const StyledPortfolioPieLegendSwatch = styled.span({
  display: 'inline-block',
  width: '16px',
  height: '8px',
  borderRadius: '2px',
  flexShrink: 0,
  opacity: 1,
});

export const StyledPortfolioPieChartPlot =
  styled.div<StyledPortfolioPieChartPlotProps>(
    {
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      width: '100%',
      minHeight: `${PORTFOLIO_PIE_CHART_HEIGHT}px`,
      flexShrink: 0,
      boxSizing: 'border-box',
      overflow: 'visible',
      alignSelf: 'center',
      position: 'relative',
      padding: '0 12px',

      '& > div': {
        width: '100%',
        height: `${PORTFOLIO_PIE_CHART_HEIGHT}px`,
        minHeight: `${PORTFOLIO_PIE_CHART_HEIGHT}px`,
      },
    },
    ({ skeleton }) =>
      skeleton
        ? {
            minHeight: '280px',
            '& > div': {
              minHeight: '280px',
            },
          }
        : {},
  );

export const StyledPortfolioPieChartEmpty = styled.p({
  margin: 0,
  padding: '24px 0',
  width: '100%',
  textAlign: 'center',
  fontSize: '14px',
  lineHeight: '140%',
  fontWeight: 400,
  fontFamily: "'Work Sans', sans-serif",
  color: '#5C5C5C',
});
